## Submitted testbench
```systemverilog
module tb;

  // ------------------------------------------------------------
  // Parameters
  // ------------------------------------------------------------
  localparam int CLK_HALF = 4;                 // 8‑ns period → 125 MHz
  localparam logic [15:0] PRESCALE_VAL = 16'd5;

  // ------------------------------------------------------------
  // Clock and reset
  // ------------------------------------------------------------
  logic clk = 0;
  always #CLK_HALF clk = ~clk;

  logic rst = 1'b1;
  initial begin
    #20 rst = 1'b0;
    #20 rst = 1'b1;
    #20 rst = 1'b0;
  end

  // ------------------------------------------------------------
  // DUT‑visible signals (re‑exported for coverage check)
  // ------------------------------------------------------------
  logic [7:0] m_axis_tdata;
  logic       m_axis_tvalid;
  logic       m_axis_tready;
  logic [15:0] prescale = PRESCALE_VAL;
  logic       frame_error;
  logic       rxd = 1'b1;                     // UART line (output of TB)

  // AXI‑stream ready is always high
  assign m_axis_tready = 1'b1;

  // ------------------------------------------------------------
  // DUT instantiation
  // ------------------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk         (clk),
    .rst         (rst),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd         (rxd),
    .busy        (),          // unused
    .overrun_error(),        // unused
    .frame_error (frame_error),
    .prescale    (prescale)
  );

  // ------------------------------------------------------------
  // Task: send one byte and force a framing error (stop bit low)
  // ------------------------------------------------------------
  task automatic send_byte_error(input byte unsigned data);
    int bit_clks = int'(prescale) * 8;

    // start bit – low for one bit period
    rxd = 1'b0;
    #bit_clks;

    // 8 data bits, LSB first
    for (int i = 0; i < 8; i++) begin
      rxd = data[i];
      #bit_clks;
    end

    // stop bit – drive low to generate a frame error
    rxd = 1'b0;
    #bit_clks;
  endtask

  // ------------------------------------------------------------
  // Coverage check – finish when R29 condition is satisfied
  // ------------------------------------------------------------
  always @(posedge clk) begin
    if (!rst) begin
      // $past() references the value from the previous rising edge
      if (!$past(rst) &&                     // rst was low in previous cycle
          $past(frame_error) &&               // frame_error was high last cycle
          $past(m_axis_tvalid) &&             // m_axis_tvalid was high last cycle
          $past(m_axis_tready) &&             // m_axis_tready was high last cycle
          ($past(m_axis_tdata) == 8'h3C) &&   // data was 0x3C last cycle
          !m_axis_tvalid &&                   // now tvalid is low
          (m_axis_tdata == 8'h3C)) begin      // and data still 0x3C
        $finish;   // successful completion
      end
    end
  end

  // ------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------
  initial begin
    // Wait until reset is released
    @(negedge rst);
    #1;

    // Trigger the error‑inducing transaction with data 0x3C
    send_byte_error(8'h3C);

    // Safety timeout – should never be reached if coverage is hit
    #5000000;
    $display("Timeout – coverage point not observed");
    $finish;
  end

  // ------------------------------------------------------------
  // Initialise UART line (idle state)
  // ------------------------------------------------------------
  initial rxd = 1'b1;

endmodule
